def write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True); path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def build_html(paths: dict[str, str]) -> str:
    def p(role: str, text: str, cls: str = "") -> str: return f'<p class="{cls}" data-copy-role="{role}">{html.escape(text)}</p>'
    def img(asset: str, alt: str, cls: str = "") -> str: return f'<img class="{cls}" src="/{paths[asset]}" alt="{html.escape(alt)}">'
    hero = f'''<section class="hero" id="hero" data-customer-state="ORIENT"><div class="hero-frame"><div class="hero-photo"></div><div class="hero-copy"><p class="kicker">なぎのみらい｜福岡市</p><h1 data-copy-role="SIGNATURE"><span><i>選ぶ前に、</i></span><span><i>まず知る。</i></span></h1>{p('WHAT','受ける、学ぶ、知る。','hero-signature')}{p('CONTEXT','3つのサービスを、内容から選べます。','hero-lead')}<div class="hero-actions"><a class="line-link" href="#selector">サービスを見る ↓</a><a class="line-link" href="{INSTAGRAM}" target="_blank" rel="noreferrer">相談する ↗</a></div></div><div class="hero-handoff">知る → 選ぶ</div></div></section>'''
    selector = f'''<section class="selector" id="selector" data-customer-state="CHOOSE"><div class="selector-sticky"><div class="selector-copy"><p class="kicker">目的から選ぶ</p><h2 data-copy-role="SIGNATURE">今の目的は、<br>どれに近いですか。</h2>{p('SUPPORT','受けたい。学びたい。まず内容を知りたい。','selector-lead')}<div class="selector-rows"><button class="selector-row" data-service="treatment" aria-current="true"><span>01</span><span><b>ドライヘッドスパ</b><small>施術を受けたい</small></span><span>↗</span></button><button class="selector-row" data-service="school" aria-current="false"><span>02</span><span><b>ヘッドスパスクール</b><small>ヘッドスパを学びたい</small></span><span>↗</span></button><button class="selector-row" data-service="healing" aria-current="false"><span>03</span><span><b>ヒーリングサロン</b><small>まず、内容を知りたい</small></span><span>↗</span></button></div></div><div class="selector-stage" data-service="treatment">{img('A05','サービスを受ける場面の参考ビジュアル')}<strong class="stage-word">ドライヘッドスパ</strong><span class="stage-fact">○○分 / ○○円</span></div><div class="selector-progress"><i></i></div></div></section>'''
    def service(kind: str, asset: str, title: str, lead: str, facts: list[tuple[str, str]], cls: str) -> str:
        fact_html=''.join(f'<div class="fact"><strong>{html.escape(k)}</strong><b>{html.escape(v)}</b></div>' for k,v in facts)
        extra = '<div class="school-grid"><div><strong>01</strong><span>基礎を知る</span></div><div><strong>02</strong><span>実技を練習</span></div><div><strong>03</strong><span>振り返る</span></div></div>' if kind=='school' else '<div class="healing-map"><div>どんなサービスか</div><div>最初に確認すること</div><div>過ごし方を相談する</div></div>' if kind=='healing' else ''
        return f'''<section class="service-scene {cls}" id="{kind}" data-customer-state="{'EVALUATE' if kind!='healing' else 'UNDERSTAND'}"><div class="service-sticky"><div class="service-visual">{img(asset,'サービス内容を説明するための参考ビジュアル')}</div><div class="service-copy"><p class="kicker">{kind.upper()}</p><h2 data-copy-role="SIGNATURE">{html.escape(title)}</h2>{p('PRIMARY',lead)}{extra}<div class="service-facts">{fact_html}</div></div></div></section>'''
    trust = '''<section class="trust" id="trust" data-customer-state="TRUST"><div class="trust-grid"><div><p class="kicker">確認できること</p><h2 data-copy-role="SIGNATURE">分からないことを、<br>残さない。</h2><p data-copy-role="PRIMARY">内容・料金・時間・流れ。相談する前に、判断に必要な情報を順番に確認できる構成です。</p></div><div class="trust-slot"><div>実際の担当者｜制作時に差し替え</div><div>資格・経験｜制作時に差し替え</div><div>場所・予約方法｜公式情報を反映</div></div></div></section>'''
    comparison = '''<section class="comparison" id="comparison" data-customer-state="COMPARE"><p class="kicker">同じ視界で比べる</p><h2 data-copy-role="SIGNATURE">3つの入口を、<br>同じ視界で比べる。</h2><p class="comparison-lead" data-copy-role="SUPPORT">受ける、学ぶ、知る。目的に近い選択肢と、確認する情報が異なります。</p><div class="compare-grid"><article class="compare-card"><strong>受ける</strong><h3>ドライヘッドスパ</h3><p>触れる内容、時間、料金、流れを確認してから選ぶ。</p></article><article class="compare-card"><strong>学ぶ</strong><h3>ヘッドスパスクール</h3><p>実技、練習、振り返り。学ぶ進め方を確認する。</p></article><article class="compare-card"><strong>知る</strong><h3>ヒーリングサロン</h3><p>どんなサービスか、確認事項から輪郭をつかむ。</p></article></div></section>'''
    faq = '''<section class="faq" id="faq" data-customer-state="RESOLVE"><p class="kicker">相談前に確認する</p><h2 data-copy-role="SIGNATURE">気になることから、<br>確認する。</h2><p class="faq-lead" data-copy-role="SUPPORT">決めきれない点を、項目ごとに整理しています。</p><div class="faq-list"><details class="faq-item"><summary>料金と時間を先に確認できますか。</summary><p>施術は○○分・○○円、講座は全○回・○○時間程度。制作時に正式情報へ差し替えます。</p></details><details class="faq-item"><summary>当日は何を確認しますか。</summary><p>希望するサービス、気になること、当日の流れを最初に確認します。</p></details><details class="faq-item"><summary>まだサービスを決めきれません。</summary><p>受ける、学ぶ、知るのどれに近いかだけ伝えて相談できます。</p></details><details class="faq-item"><summary>予約前に見ておくことはありますか。</summary><p>料金、時間、場所、流れを見て、分からない点を整理しておくと相談が進みます。</p></details></div></section>'''
    contact = f'''<section class="contact" id="contact" data-customer-state="CONTACT"><div class="contact-sticky"><div class="contact-visual"></div><div class="contact-copy"><p class="kicker">相談する</p><h2 data-copy-role="SIGNATURE">気になることが一つあれば、<br>そこから相談できます。</h2>{p('PRIMARY','選んだサービスや、まだ決めきれないことを公式Instagramで相談できます.','contact-lead')}<a class="line-link" href="{INSTAGRAM}" target="_blank" rel="noreferrer">公式Instagramで相談する ↗</a></div><div class="contact-box"><span>相談先</span><strong>@happyfuture_02</strong><div class="merge-routes"><div class="merge-route"><span>受ける</span><span>→</span></div><div class="merge-route"><span>学ぶ</span><span>→</span></div><div class="merge-route"><span>知る</span><span>→</span></div></div><div class="contact-destination">ひとつの相談先へ</div></div></div></section>'''
    closing = '''<section class="closing" id="closing" data-customer-state="CONTACT"><div><p class="kicker">なぎのみらい｜福岡市</p><h2 data-copy-role="SIGNATURE">知ってから、<br>相談する。</h2><p data-copy-role="SUPPORT">あなたの目的に近い入口から、確認できます。</p><div class="line"></div></div></section>'''
    return f'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>なぎのみらい｜選ぶ前に、まず知る。</title><style>{CSS}</style></head><body><header class="site-header"><a class="brand" href="#hero">なぎのみらい</a><div class="header-right"><span class="area">福岡市</span><a class="header-cta" href="{INSTAGRAM}" target="_blank" rel="noreferrer">相談する ↗</a></div></header><aside class="route-rail" aria-hidden="true"><i class="route-progress"></i><b class="route-dot"></b><b class="route-dot"></b><b class="route-dot"></b><b class="route-dot"></b><span>知る → 選ぶ → 確認する → 相談する</span></aside><main>{hero}{selector}{service('treatment','A05','ドライヘッドスパを受ける。\nその前に知りたいこと。','時間、料金、流れ。相談する前に、判断に必要な情報を整理します。',[('時間','○○分'),('料金','○○円'),('流れ','確認 → 施術')],'treatment')}{service('school','A06','学ぶなら、\n内容と進め方から。','実技、練習、振り返り。学ぶ入口で確認することを順番に見せます。',[('回数','全○回'),('時間','○○時間程度'),('流れ','知る → 練習')],'school')}{service('healing','A07','ヒーリングは、\nまず内容から。','どんな時間か、何を確認するか。決めつけずにサービスの輪郭を整理します。',[('時間','○○分'),('料金','○○円'),('流れ','対話 → 確認')],'healing')}{trust}{comparison}{faq}{contact}{closing}</main><div class="self-note">本ページの人物・施術・空間写真は、サービス内容を説明するための参考ビジュアルです。公開施工・実在スタッフの記録写真ではありません。</div><script>{JS}</script></body></html>'''


def copy_assets(site: Path) -> dict[str, str]:
    raw = H.F.copy_assets(site)
    return {item["asset_id"]: item["output"] for item in raw.values()} if isinstance(raw, dict) else {item["asset_id"]: item["output"] for item in raw}


def make_self_contained(source: Path, destination: Path, site: Path) -> dict[str, Any]:
    markup = source.read_text(encoding="utf-8")
    for rel in ("assets/photography/nagi_no_mirai/welcome_human.png", "assets/photography/nagi_no_mirai/sensory_detail.png", "assets/photography/nagi_no_mirai/school_learning_context.png", "assets/photography/nagi_no_mirai/hero_treatment_space.png", "assets/photography/nagi_no_mirai/healing_consultation_context.png", "assets/photography/nagi_no_mirai/hand_technique.jpg"):
        path = site / rel; mime = mimetypes.guess_type(path.name)[0] or "application/octet-stream"; uri = f"data:{mime};base64,{base64.b64encode(path.read_bytes()).decode('ascii')}"; markup = markup.replace("/" + rel, uri)
    for name, filename in (("Noto Sans JP", "NotoSansJP-Variable.ttf"), ("Inter Tight", "InterTight-Variable.ttf"), ("Zen Kaku Gothic New", "ZenKakuGothicNew-600.ttf")):
        path = site / "assets" / "fonts" / filename; uri = f"data:font/ttf;base64,{base64.b64encode(path.read_bytes()).decode('ascii')}"; markup = markup.replace("<style>", f"<style>@font-face{{font-family:'{name}';src:url({uri}) format('truetype');font-display:swap;font-weight:100 900;}}", 1)
    destination.parent.mkdir(parents=True, exist_ok=True); destination.write_text(markup, encoding="utf-8")
    return {"file": destination.name, "single_file": True, "external_asset_references": bool(re.search(r"(?:src|url\()[\"']?/?assets/", markup)), "external_cta_links_allowed": True, "size_bytes": destination.stat().st_size}


async def qa(url: str, out: Path) -> dict[str, Any]:
    from playwright.async_api import async_playwright
    widths = (320, 360, 375, 390, 430, 768, 1024, 1280, 1440); rows=[]
    public = (OUT / "site" / "index.html").read_text(encoding="utf-8")
    visible = re.sub(r"<style.*?</style>|<script.*?</script>", " ", public, flags=re.S | re.I); visible = re.sub(r"<[^>]+>", " ", html.unescape(visible))
    leak_hits = [x for x in INTERNAL_WORDS if x.casefold() in visible.casefold()]; instruction_hits = [x for x in UI_INSTRUCTIONS if x.casefold() in visible.casefold()]; trust_hits = [x for x in TRUST_BANS if x.casefold() in visible.casefold()]
    async with async_playwright() as p:
        for width in widths:
            browser=await p.chromium.launch(headless=True,args=["--no-sandbox"]); page=await browser.new_page(viewport={"width":width,"height":1000 if width>=768 else 844}); ce=[]; pe=[]; rf=[]; page.on("console",lambda m: ce.append(m.text) if m.type=="error" else None); page.on("pageerror",lambda e: pe.append(str(e))); page.on("requestfailed",lambda r: rf.append(r.url)); await page.goto(url,wait_until="networkidle"); state=await page.evaluate("""()=>({overflow:Math.max(0,document.documentElement.scrollWidth-innerWidth),images:[...document.images].every(x=>x.complete&&x.naturalWidth>0),scenes:document.querySelectorAll('[data-customer-state]').length,route:!!document.querySelector('.route-rail'),sticky:!!document.querySelector('.selector-sticky'),contact:!!document.querySelector('#contact'),scrollTrap:getComputedStyle(document.documentElement).overflow==='hidden'})"""); row={"width":width,**state,"console_errors":ce,"page_errors":pe,"request_failures":rf,"pass":state["overflow"]==0 and state["images"] and state["scenes"]>=10 and state["route"] and state["sticky"] and state["contact"] and not state["scrollTrap"] and not ce and not pe and not rf}; rows.append(row); await page.close(); await browser.close()
    report={"schema_version":"round2u_browser_qa_v1","status":"PASS" if all(r["pass"] for r in rows) else "FAIL","rows":rows,"breakpoints":list(widths),"public_internal_leak":leak_hits,"ui_instruction_leak":instruction_hits,"trust_fabrication_hits":trust_hits}; write_json(out / "reports" / "browser_qa.json",report); return report


async def evidence(url: str, out: Path) -> dict[str, Any]:
    from playwright.async_api import async_playwright
    cap=out/"human_review_pack"/"captures"; rec=out/"human_review_pack"/"recordings"; cap.mkdir(parents=True,exist_ok=True); rec.mkdir(parents=True,exist_ok=True); shots=[]; videos=[]
    async with async_playwright() as p:
        browser=await p.chromium.launch(headless=True,args=["--no-sandbox"])
        for width,height,device in ((1440,1000,"desktop"),(390,844,"mobile")):
            page=await browser.new_page(viewport={"width":width,"height":height}); await page.goto(url,wait_until="networkidle")
            for name,target in (("hero_start","#hero"),("hero_transformed","#hero"),("selector_sticky","#selector"),("treatment","#treatment"),("school","#school"),("healing","#healing"),("comparison","#comparison"),("contact_merge","#contact"),("closing","#closing")):
                await page.locator(target).scroll_into_view_if_needed()
                if name == "hero_transformed":
                    await page.evaluate("() => scrollTo(0, Math.max(0, document.querySelector('#hero').offsetTop + innerHeight * .55))")
                    await page.wait_for_timeout(650)
                else:
                    await page.wait_for_timeout(400)
                await page.screenshot(path=str(cap/f"{device}_{name}.png"),full_page=False); shots.append(f"human_review_pack/captures/{device}_{name}.png")
            await page.close()
        for width,height,device in ((1440,1000,"desktop"),(390,844,"mobile")):
            context=await browser.new_context(viewport={"width":width,"height":height},record_video_dir=str(rec),record_video_size={"width":width,"height":height}); page=await context.new_page(); await page.goto(url,wait_until="networkidle"); await page.wait_for_timeout(900); total=await page.evaluate("document.documentElement.scrollHeight");
            for ratio in (0,.18,.36,.54,.72,.9,1): await page.evaluate("r=>scrollTo(0,(document.documentElement.scrollHeight-innerHeight)*r)",ratio); await page.wait_for_timeout(520)
            video=page.video; await context.close()
            if video: source=await video.path(); dest=rec/f"{device}_full_page_scroll.webm"; shutil.copy2(source,dest); Path(source).unlink(missing_ok=True); videos.append(f"human_review_pack/recordings/{dest.name}")
        await browser.close()
    return {"screenshots":shots,"recordings":videos,"screenshot_count":len(shots),"recording_count":len(videos)}


def main() -> int:
    if OUT.exists(): shutil.rmtree(OUT)
    site=OUT/"site"; site.mkdir(parents=True); paths=copy_assets(site); markup=build_html(paths); (site/"index.html").write_text(markup,encoding="utf-8"); (site/"final.html").write_text(markup,encoding="utf-8")
    self_contained=make_self_contained(site/"index.html",OUT/"Nagi_Round2U_Creative_Translation_Integration_SelfContained.html",site)
    human=OUT/"human_review_html"; human.mkdir(parents=True); shutil.copy2(site/"index.html",human/"index.html"); shutil.copy2(site/"final.html",human/"final.html"); shutil.copytree(site/"assets",human/"assets")
    server,thread,url=H.F.serve(site)
    try: browser_report=asyncio.run(qa(url,OUT)); pack=asyncio.run(evidence(url,OUT))
    finally: server.shutdown(); thread.join(timeout=2)
